CREATE TABLE IF NOT EXISTS wiki_autoopt_events (id TEXT PRIMARY KEY, token TEXT NOT NULL, version TEXT NOT NULL, prompt TEXT NOT NULL, run_id TEXT NOT NULL, context_id TEXT NOT NULL, code TEXT NOT NULL, family TEXT NOT NULL, family_key TEXT NOT NULL, kind TEXT NOT NULL, draft_id TEXT, data TEXT NOT NULL, response TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wiki_autoopt_context ON wiki_autoopt_events(context_id,kind);
CREATE INDEX IF NOT EXISTS wiki_autoopt_draft ON wiki_autoopt_events(draft_id,kind);
CREATE INDEX IF NOT EXISTS wiki_autoopt_retention ON wiki_autoopt_events(created_at);
CREATE TABLE IF NOT EXISTS wiki_autoopt_stats (version TEXT NOT NULL, prompt TEXT NOT NULL, scope TEXT NOT NULL, scope_id TEXT NOT NULL, family TEXT NOT NULL, stats TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL, PRIMARY KEY(version,prompt,scope,scope_id));
CREATE TRIGGER IF NOT EXISTS wiki_autoopt_accumulate AFTER INSERT ON wiki_autoopt_events BEGIN
      INSERT OR IGNORE INTO wiki_autoopt_stats VALUES(NEW.version,NEW.prompt,'global','*','*','{}',NEW.created_at);
      INSERT OR IGNORE INTO wiki_autoopt_stats VALUES(NEW.version,NEW.prompt,'family',NEW.family_key,NEW.family,'{}',NEW.created_at);
      INSERT OR IGNORE INTO wiki_autoopt_stats VALUES(NEW.version,NEW.prompt,'run',NEW.run_id,'*','{}',NEW.created_at);
      UPDATE wiki_autoopt_stats SET stats=json_set(stats,'$.validationAttempts',COALESCE(json_extract(stats,'$.validationAttempts'),0)+(NEW.kind = 'validation'),'$.validationFailures',COALESCE(json_extract(stats,'$.validationFailures'),0)+((NEW.kind = 'validation') AND NOT COALESCE(json_extract(NEW.data, '$.valid'),0)),'$.successfulFirstPass',COALESCE(json_extract(stats,'$.successfulFirstPass'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0) AND (COALESCE(json_extract(NEW.data, '$.attempt'),0) = 1)),'$.firstAttempts',COALESCE(json_extract(stats,'$.firstAttempts'),0)+((NEW.kind = 'validation') AND (COALESCE(json_extract(NEW.data, '$.attempt'),0) = 1)),'$.published',COALESCE(json_extract(stats,'$.published'),0)+(NEW.kind = 'published'),'$.publicationsWithAttemptHistory',COALESCE(json_extract(stats,'$.publicationsWithAttemptHistory'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.attempt'),0) > 0),'$.firstPassPublished',COALESCE(json_extract(stats,'$.firstPassPublished'),0)+((NEW.kind = 'published') AND (COALESCE(json_extract(NEW.data, '$.attempt'),0) = 1)),'$.attemptsForPublished',COALESCE(json_extract(stats,'$.attemptsForPublished'),0)+((NEW.kind = 'published') * COALESCE(json_extract(NEW.data, '$.attempt'),0)),'$.wordsSuccessful',COALESCE(json_extract(stats,'$.wordsSuccessful'),0)+((NEW.kind = 'published') * COALESCE(json_extract(NEW.data, '$.words'),0)),'$.sectionsSuccessful',COALESCE(json_extract(stats,'$.sectionsSuccessful'),0)+((NEW.kind = 'published') * COALESCE(json_extract(NEW.data, '$.sections'),0)),'$.referencesSuccessful',COALESCE(json_extract(stats,'$.referencesSuccessful'),0)+((NEW.kind = 'published') * COALESCE(json_extract(NEW.data, '$.references'),0)),'$.preservedExisting',COALESCE(json_extract(stats,'$.preservedExisting'),0)+(NEW.kind = 'preserved'),'$.publicationFailures',COALESCE(json_extract(stats,'$.publicationFailures'),0)+(NEW.kind = 'publication_failure'),'$.deferred',COALESCE(json_extract(stats,'$.deferred'),0)+(NEW.kind = 'deferred'),'$.needsReview',COALESCE(json_extract(stats,'$.needsReview'),0)+(NEW.kind = 'needs_review'),'$.elapsedMsSuccessful',COALESCE(json_extract(stats,'$.elapsedMsSuccessful'),0)+((NEW.kind = 'published') * COALESCE(json_extract(NEW.data, '$.elapsedMs'),0)),'$.lengthFailures',COALESCE(json_extract(stats,'$.lengthFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'length'),'$.r32FalsePositiveLikeFailures',COALESCE(json_extract(stats,'$.r32FalsePositiveLikeFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'r32_activity_like'),'$.ruleFailures',COALESCE(json_extract(stats,'$.ruleFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'rule'),'$.markdownFailures',COALESCE(json_extract(stats,'$.markdownFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'markdown'),'$.contractFailures',COALESCE(json_extract(stats,'$.contractFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'contract'),'$.otherFailures',COALESCE(json_extract(stats,'$.otherFailures'),0)+((NEW.kind = 'validation') AND json_extract(NEW.data,'$.category') = 'other'),'$.bucket0Attempts',COALESCE(json_extract(stats,'$.bucket0Attempts'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 0),'$.bucket0Valid',COALESCE(json_extract(stats,'$.bucket0Valid'),0)+(((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0)) AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 0),'$.bucket0Published',COALESCE(json_extract(stats,'$.bucket0Published'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 0),'$.bucket1Attempts',COALESCE(json_extract(stats,'$.bucket1Attempts'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 1),'$.bucket1Valid',COALESCE(json_extract(stats,'$.bucket1Valid'),0)+(((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0)) AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 1),'$.bucket1Published',COALESCE(json_extract(stats,'$.bucket1Published'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 1),'$.bucket2Attempts',COALESCE(json_extract(stats,'$.bucket2Attempts'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 2),'$.bucket2Valid',COALESCE(json_extract(stats,'$.bucket2Valid'),0)+(((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0)) AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 2),'$.bucket2Published',COALESCE(json_extract(stats,'$.bucket2Published'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 2),'$.bucket3Attempts',COALESCE(json_extract(stats,'$.bucket3Attempts'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 3),'$.bucket3Valid',COALESCE(json_extract(stats,'$.bucket3Valid'),0)+(((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0)) AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 3),'$.bucket3Published',COALESCE(json_extract(stats,'$.bucket3Published'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 3),'$.bucket4Attempts',COALESCE(json_extract(stats,'$.bucket4Attempts'),0)+((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 4),'$.bucket4Valid',COALESCE(json_extract(stats,'$.bucket4Valid'),0)+(((NEW.kind = 'validation') AND COALESCE(json_extract(NEW.data, '$.valid'),0)) AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 4),'$.bucket4Published',COALESCE(json_extract(stats,'$.bucket4Published'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.bucket'),0) = 4),'$.tablesSuccessful',COALESCE(json_extract(stats,'$.tablesSuccessful'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.tables'),0) > 0),'$.listsSuccessful',COALESCE(json_extract(stats,'$.listsSuccessful'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.lists'),0) > 0),'$.examplesSuccessful',COALESCE(json_extract(stats,'$.examplesSuccessful'),0)+((NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.examples'),0) > 0),'$.minimumSuccessful',CASE WHEN (NEW.kind = 'published') THEN MIN(COALESCE(json_extract(stats,'$.minimumSuccessful'),COALESCE(json_extract(NEW.data, '$.words'),0)),COALESCE(json_extract(NEW.data, '$.words'),0)) ELSE json_extract(stats,'$.minimumSuccessful') END,'$.maximumSuccessful',CASE WHEN (NEW.kind = 'published') THEN MAX(COALESCE(json_extract(stats,'$.maximumSuccessful'),0),COALESCE(json_extract(NEW.data, '$.words'),0)) ELSE json_extract(stats,'$.maximumSuccessful') END,'$.learnedMinimum',CASE WHEN (NEW.kind = 'published') AND COALESCE(json_extract(NEW.data, '$.words'),0) < COALESCE(json_extract(stats,'$.learnedMinimum'),0) THEN MAX(COALESCE(json_extract(NEW.data, '$.estimatedMinimum'),0),COALESCE(json_extract(NEW.data, '$.words'),0)) ELSE MAX(COALESCE(json_extract(stats,'$.learnedMinimum'),0),COALESCE(json_extract(NEW.data, '$.observedMinimum'),0)) END,'$.consecutiveFirstPassSuccesses',CASE WHEN (NEW.kind = 'validation') AND NOT COALESCE(json_extract(NEW.data, '$.valid'),0) THEN 0 WHEN (NEW.kind = 'published') AND (COALESCE(json_extract(NEW.data, '$.attempt'),0) = 1) THEN COALESCE(json_extract(stats,'$.consecutiveFirstPassSuccesses'),0)+1 WHEN (NEW.kind = 'published') THEN 0 ELSE COALESCE(json_extract(stats,'$.consecutiveFirstPassSuccesses'),0) END),updated_at=NEW.created_at
      WHERE version=NEW.version AND prompt=NEW.prompt AND ((scope='global' AND scope_id='*') OR (scope='family' AND scope_id=NEW.family_key) OR (scope='run' AND scope_id=NEW.run_id));
    END;
